INSERT [PnS].[Schema_MRDFRequest] ([Id], [FieldName], [Type], [StartPosition], [Length], [IsActive], [Description], [Comments], [SampleValue], [DataType], [DataFormatTemplate], [DefaultValue]) VALUES (20, N'TotalSheets', N'ASCII_Alpha', 22, 3, 1, N'This field Identifies the tota l numbe r of phys ica l she ets of pa per tha t should be fe d from the input fe ede r for the ma ilpiece. If you ha ve multiple input fe eders , you will nee d a Tota l Sheets field for ea ch input fe eder. There are two of the s e fields availa ble to a ccommoda te as ma ny as two input fee ders on the ins e rter (e .g., a RAT1 with ea s t and north feeder inputs ).', N'Number of physical papers in that loan required to print pages.', N'', N'int', N'{0:d<len>}', NULL)
